package org.humanjourney.core.geography.map;
import java.util.*;
/** Pure client mirror; completed immutable snapshots swap atomically, never partial live geometry. */
public final class ClientMapState {
 public record Snapshot(MapPackets.Header header,Map<MapArea.Key,MapArea> areas,MapSpatialIndex index){public Snapshot{areas=Map.copyOf(areas);}public long count(MapArea.Kind kind){return areas.values().stream().filter(a->a.kind()==kind).count();}}
 private static final class Pending {final MapPackets.Frame[] parts;final MapPackets.Frame first;int areaCount,removedCount;Pending(MapPackets.Frame f){first=f;parts=new MapPackets.Frame[f.parts()];}boolean complete(){for(var f:parts)if(f==null)return false;return true;}}
 private Snapshot visible=empty(null);private final TreeMap<Long,Pending> pending=new TreeMap<>();private UUID session;private boolean revoked,needsResync;private String problem="";
 private static Snapshot empty(MapPackets.Header h){return new Snapshot(h,Map.of(),new MapSpatialIndex(Map.of()));}
 public Snapshot snapshot(){return visible;}public String problem(){return problem;}public boolean needsResync(){return needsResync;}
 private long sequence(){return visible.header()==null?0:visible.header().sequence();}
 public void role(boolean participant){if(!participant){revoked=true;pending.clear();visible=empty(visible.header());}else if(revoked){revoked=false;needsResync=true;}}
 public void clear(){visible=empty(null);pending.clear();session=null;revoked=false;needsResync=false;problem="";}
 private boolean bad(String why){problem=why;needsResync=true;return false;}
 private boolean old(MapPackets.Header h){var current=visible.header();return h.sequence()<=sequence()||current!=null&&(h.discovery()<current.discovery()||h.data()<current.data()||h.presentation()<current.presentation());}
 public boolean accept(MapPackets.Frame f){if(!f.valid())return bad(f.error());var h=f.header();if(session==null)session=h.session();if(!session.equals(h.session())||old(h))return false;if(f.mode()==MapPackets.Mode.CLEAR){visible=empty(h);pending.headMap(h.sequence(),true).clear();needsResync=false;problem="";return true;}if(revoked)return bad("Map transfer received while participant role revoked");var p=pending.computeIfAbsent(h.sequence(),k->new Pending(f));if(!p.first.header().equals(h)||p.first.mode()!=f.mode()||p.first.base()!=f.base()||p.parts.length!=f.parts()){pending.remove(h.sequence());return bad("Inconsistent map transaction");}if(p.parts[f.part()]!=null){if(!p.parts[f.part()].equals(f)){pending.remove(h.sequence());return bad("Conflicting duplicate map part");}return false;}p.parts[f.part()]=f;p.areaCount+=f.areas().size();p.removedCount+=f.removals().size();if(p.areaCount>MapPackets.MAX_AREAS||p.removedCount>MapPackets.MAX_AREAS){pending.remove(h.sequence());return bad("Map transaction exceeds total geography limit");}while(pending.size()>2){pending.pollFirstEntry();needsResync=true;}boolean changed=commit(p);boolean progress=true;while(progress){progress=false;for(var entry:new ArrayList<>(pending.entrySet()))if(entry.getValue().complete()&&entry.getValue().first.mode()==MapPackets.Mode.DELTA&&entry.getValue().first.base()==sequence()){progress=commit(entry.getValue());changed|=progress;if(progress)break;}}return changed;}
 private boolean commit(Pending p){if(!p.complete())return false;var f=p.first;var h=f.header();if(old(h)){pending.remove(h.sequence());return false;}if(f.mode()==MapPackets.Mode.DELTA&&f.base()!=sequence()){if(f.base()<sequence())pending.remove(h.sequence());return bad("Map delta is missing its exact base; full resync requested");}try{var entries=f.mode()==MapPackets.Mode.FULL?new TreeMap<MapArea.Key,MapArea>():new TreeMap<>(visible.areas());var added=new HashSet<MapArea.Key>();var removed=new HashSet<MapArea.Key>();for(var part:p.parts){for(var key:part.removals()){if(!removed.add(key))throw new IllegalArgumentException("duplicate map removal");entries.remove(key);}for(var area:part.areas()){if(!added.add(area.key()))throw new IllegalArgumentException("duplicate map area");entries.put(area.key(),area);}}if(!Collections.disjoint(added,removed))throw new IllegalArgumentException("map key both removed and updated");long macros=entries.keySet().stream().filter(k->k.kind()==MapArea.Kind.MACRO).count();if(macros>512||entries.size()-macros>4096)throw new IllegalArgumentException("map catalog limit exceeded");for(var area:entries.values())if(!area.parent().isEmpty()){var parent=entries.get(new MapArea.Key(MapArea.Kind.MACRO,area.parent()));if(parent==null||!parent.dimension().equals(area.dimension()))throw new IllegalArgumentException("invalid/redacted map parent");}var next=new Snapshot(h,entries,new MapSpatialIndex(entries));visible=next;pending.headMap(h.sequence(),true).clear();needsResync=false;problem="";return true;}catch(IllegalArgumentException e){pending.remove(h.sequence());return bad(e.getMessage());}}
}
